class Solution:
    def kBigIndices(self, nums: List[int], k: int) -> int:
        n = len(nums)
        m = max(nums)
        def make():
            return [0] * (m + 1)
        def upd(t, i):
            while i <= m:
                t[i] += 1
                i += i & -i
        def qry(t, i):
            s = 0
            while i > 0:
                s += t[i]
                i -= i & -i
            return s
        L, R = make(), make()
        left = [0] * n
        right = [0] * n
        for i, x in enumerate(nums):
            left[i] = qry(L, x - 1)
            upd(L, x)
        for i in range(n - 1, -1, -1):
            right[i] = qry(R, nums[i] - 1)
            upd(R, nums[i])
        return sum(1 for i in range(n) if left[i] >= k and right[i] >= k)

