    int qry(int i) { int s = 0; for (; i > 0; i -= i & -i) s += tr[i]; return s; }
    int kBigIndices(vector<int>& nums, int k) {
        int n = nums.size();
        m = *max_element(nums.begin(), nums.end());
        tr.assign(m + 1, 0);
        vector<int> left(n), right(n);
        for (int i = 0; i < n; i++) { left[i] = qry(nums[i] - 1); upd(nums[i]); }
        fill(tr.begin(), tr.end(), 0);
        for (int i = n - 1; i >= 0; i--) { right[i] = qry(nums[i] - 1); upd(nums[i]); }
        int ans = 0;
        for (int i = 0; i < n; i++) if (left[i] >= k && right[i] >= k) ans++;
        return ans;
    }
};

