class Solution:
    def kBigIndices(self, nums: List[int], k: int) -> int:
        def count_smaller(a):
            res = [0] * len(a)
            def ms(lo, hi):
                if hi - lo <= 1:
                    return
                m = (lo + hi) // 2
                ms(lo, m)
                ms(m, hi)
                j = m
                for i in range(lo, m):
                    while j < hi and a[j] < a[i]:
                        j += 1
                    res[i] += j - m
                a[lo:hi] = sorted(a[lo:hi])
            ms(0, len(a))
            return res
        left = count_smaller(list(nums))
        right = count_smaller(list(nums))[::-1]
        right = count_smaller(nums[::-1])[::-1]
        return sum(1 for i in range(len(nums)) if left[i] >= k and right[i] >= k)

