class Solution {
public:
    vector<int> countSmaller(vector<int> a) {
        int n = a.size();
        vector<int> res(n, 0);
        function<void(int,int)> ms = [&](int lo, int hi) {
            if (hi - lo <= 1) return;
            int m = (lo + hi) / 2;
            ms(lo, m); ms(m, hi);
            int j = m;
            for (int i = lo; i < m; i++) {
                while (j < hi && a[j] < a[i]) j++;
                res[i] += j - m;
            }
            inplace_merge(a.begin() + lo, a.begin() + m, a.begin() + hi);
        };
        ms(0, n);
        return res;
    }
    int kBigIndices(vector<int>& nums, int k) {
        vector<int> left = countSmaller(nums);
        vector<int> rev = nums;
        reverse(rev.begin(), rev.end());
        vector<int> rc = countSmaller(rev);
        reverse(rc.begin(), rc.end());
        int ans = 0;
        for (int i = 0; i < (int)nums.size(); i++)
            if (left[i] >= k && rc[i] >= k) ans++;
        return ans;
    }
};

