class Solution {
    int[] res;
    void ms(long[] a, int lo, int hi) {
        if (hi - lo <= 1) return;
        int m = (lo + hi) / 2;
        ms(a, lo, m); ms(a, m, hi);
        int j = m;
        for (int i = lo; i < m; i++) {
            while (j < hi && a[j] < a[i]) j++;
            res[i] += j - m;
        }
        long[] t = Arrays.copyOfRange(a, lo, hi);
        Arrays.sort(t);
        System.arraycopy(t, 0, a, lo, hi - lo);
    }
    int[] countSmaller(int[] arr) {
        int n = arr.length;
        res = new int[n];
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = arr[i];
        ms(a, 0, n);
        return res.clone();
    }
    public int kBigIndices(int[] nums, int k) {
        int[] left = countSmaller(nums);
        int[] rv = new int[nums.length];
        for (int i = 0; i < nums.length; i++) rv[i] = nums[nums.length - 1 - i];
        int[] rc = countSmaller(rv);
        int ans = 0;
        for (int i = 0; i < nums.length; i++)
            if (left[i] >= k && rc[nums.length - 1 - i] >= k) ans++;
        return ans;
    }
}

