var kBigIndices = function(nums, k) {
    function countSmaller(arr) {
        const a = [...arr];
        const res = Array(a.length).fill(0);
        function ms(lo, hi) {
            if (hi - lo <= 1) return;
            const m = (lo + hi) >> 1;
            ms(lo, m); ms(m, hi);
            let j = m;
            for (let i = lo; i < m; i++) {
                while (j < hi && a[j] < a[i]) j++;
                res[i] += j - m;
            }
            const t = a.slice(lo, hi).sort((x, y) => x - y);
            for (let i = lo; i < hi; i++) a[i] = t[i - lo];
        }
        ms(0, a.length);
        return res;
    }
    const left = countSmaller(nums);
    const rc = countSmaller([...nums].reverse()).reverse();
    let ans = 0;
    for (let i = 0; i < nums.length; i++)
        if (left[i] >= k && rc[i] >= k) ans++;
    return ans;
};
